45|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
46|  const [selection, setSelection] = useState<MusicSelection | null>(null);
47|  const [musicFailed, setMusicFailed] = useState(false);
48|  const [currentId, setCurrentId] = useState<string | null>(null);
49|  const [fadeSec, setFadeSec] = useState(0);
50|  const [isFallback, setIsFallback] = useState(false);
51|  const [playlistOn, setPlaylistOn] = useState(false);
52|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s])), [scenes]);
53|  const schedRef = useRef<SchedulerState>(initScheduler());
54|  const liveRef = useRef({ activeId, manifest, selection, currentId, byId, playlistOn });
55|  liveRef.current = { activeId, manifest, selection, currentId, byId, playlistOn };
