120|  useEffect(() => {
121|    if (!manifest) return;
122|    const st = liveRef.current;
123|    if (st.activeId) observe(st.activeId);
124|  }, [manifest, observe]);
125|
126|  useEffect(() => {
127|    const snapshot = () =>
128|      [...document.querySelectorAll<HTMLElement>("section[data-scene-id]")].map((el) => ({
129|        id: el.dataset.sceneId ?? "",
130|        top: el.getBoundingClientRect().top,
