142|    const first = readActive();
143|    if (first) observe(first);
144|    const timer = window.setInterval(() => {
145|      // Settle an expired dwell, or re-check the active scene after a hold.
146|      const st = liveRef.current;
147|      if (!st.manifest || !st.selection || !st.activeId) return;
