1|// Persisted music prefs: mode, soundtrack, and style. Storage can
2|// throw (private mode), so every access is guarded and falls back.
3|import type { PersistedMusicPrefs } from "@/core/music";
4|
5|export const MUSIC_PREFS_KEY = "lectoria.music.v1";
6|
7|export function loadMusicPrefs(): PersistedMusicPrefs | null {
8|  try {
9|    if (typeof window === "undefined") return null;
10|    const raw = window.localStorage.getItem(MUSIC_PREFS_KEY);
11|    if (!raw) return null;
12|    const json: unknown = JSON.parse(raw);
13|    if (typeof json !== "object" || json === null) return null;
14|    const { mode, soundtrackId, style } = json as Record<string, unknown>;
15|    return {
16|      mode: mode === "random" ? "random" : "soundtrack",
17|      soundtrackId: typeof soundtrackId === "string" ? soundtrackId : null,
18|      style: typeof style === "string" ? style : null,
19|    };
20|  } catch {
21|    return null;
22|  }
23|}
24|
25|export function saveMusicPrefs(prefs: PersistedMusicPrefs): void {
26|  try {
27|    if (typeof window === "undefined") return;
28|    window.localStorage.setItem(MUSIC_PREFS_KEY, JSON.stringify(prefs));
29|  } catch {
30|    // Private mode: playback continues without persistence.
31|  }
