450|function isRecord(value: unknown): value is Record<string, unknown> {
451|  return typeof value === "object" && value !== null && !Array.isArray(value);
452|}
453|
454|function isOneOf<T extends string>(value: unknown, allowed: readonly T[]): value is T {
455|  return typeof value === "string" && allowed.some((entry) => entry === value);
456|}
457|
458|function isVector8(value: unknown): value is Vector8 {
459|  if (!isRecord(value)) return false;
460|  return EMOTIONS.every(
461|    (id: EmotionId) =>
462|      typeof value[id] === "number" &&
463|      Number.isFinite(value[id]) &&
464|      (value[id] as number) >= 0 &&
465|      (value[id] as number) <= 1,
466|  );
467|}
468|
469|function isUnit(value: unknown): value is number {
470|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1;
471|}
472|
473|function isSrc(value: unknown): value is string {
474|  return (
475|    typeof value === "string" && (value.startsWith("/music/") || value.startsWith("https://"))
476|  );
477|}
478|
479|function isNonEmptyString(value: unknown): value is string {
480|  return typeof value === "string" && value !== "";
481|}
482|
483|// Fail loudly on a bad drop-in manifest so broken files never play quiet.
484|export function parseManifest(json: unknown): MusicManifest {
485|  if (!isRecord(json)) throw new Error("manifest must be an object");
486|  if (json.version !== 3 && json.version !== 2) {
487|    throw new Error(`unsupported manifest version: ${String(json.version)}`);
488|  }
489|  // A v2 manifest becomes one implicit soundtrack holding every track.
490|  if (json.version === 2) {
491|    if (!Array.isArray(json.tracks)) throw new Error("manifest tracks must be an array");
492|    const tracks = json.tracks.map((entry, i) => parseTrack(entry, i, "default", "orchestral"));
493|    return {
494|      version: 3,
495|      styles: [{ id: "orchestral", name: "Orquesta" }],
496|      soundtracks: [{ id: "default", name: "Default", style: "orchestral" }],
497|      tracks,
498|      playlists: [],
499|    };
500|  }
